    content: `
## 水分補給はペットの健康の基本

水は犬と猫の体重の約60〜70%を占める、生命維持に不可欠な要素です。十分な水分摂取は、体温調節・栄養素の運搬・老廃物の排出・臓器の正常な機能維持に必要です。

特にシニアのペットや腎臓に負担がかかりやすい猫は、水分不足に注意が必要です。

## 犬と猫の1日の水分摂取量の目安

一般的な目安として、犬も猫も体重1kgあたり約50〜60mlの水分が必要とされています（フードに含まれる水分を含む）。

ただし、運動量・気温・フードの種類（ドライ/ウェット）・年齢・健康状態によって必要量は変わります。具体的な量は獣医師に相談してください。

## 脱水のサインを見逃さない

### 犬の脱水サイン

- 皮膚の弾力低下（首の後ろの皮膚をつまんで離しても戻りが遅い）
- 歯茎が乾いている、またはベタつく
- 元気がない・ぐったりしている
- 目がくぼんで見える
- 食欲の低下
- 尿の量が減る、色が濃い

### 猫の脱水サイン

- 皮膚の弾力低下（犬と同様のチェック方法）
- 目のくぼみ
- 口の中の乾燥
- 食欲不振
- 活動量の低下
- 便秘

猫はもともと水を飲む量が少ない動物のため、意識的に水分摂取をサポートする必要があります。

## 水分摂取を増やす工夫

### 水飲み場を増やす

家の中の複数箇所に水飲み場を設置しましょう。猫は特に、食事場所とは別の場所に置いた水を好む傾向があります。

### 水の種類を工夫する

- **流水**: 流れる水を好むペットには、循環式の給水器が効果的
- **ぬるま湯**: 冷たい水より温かい水を好む個体もいます
- **新鮮な水**: こまめに水を入れ替え、常に新鮮な状態を保つ

### ウェットフードを活用する

ウェットフード（缶詰・パウチ）は約70〜80%が水分です。ドライフードだけの食事に比べ、水分摂取量を大幅に増やせます。

### ドライフードをふやかす

ドライフードにぬるま湯を加えてふやかすと、フードと一緒に水分を摂取できます。シニアのペットには消化面でもメリットがあります。

関連記事: [老猫の食欲がない時の対策](/blog/senior-neko-shokuji)、[シニア犬の元気がない原因と対策](/blog/senior-inu-genki-nai)

## 飲み水に栄養をプラスする

毎日の飲み水にサプリメントを混ぜることで、水分補給と栄養補給を同時に行える方法があります。水溶性ケイ素は味やにおいの変化が少ないため、飲み水に加えてもペットが気づかずに飲んでくれることが多いです。

普段の水分補給のついでに、骨・関節・被毛の健康維持に関わるミネラルを摂取できるのがメリットです。

## 脱水が疑われる場合の対処

軽度の脱水であれば、少量ずつ水を与えることで改善が見込めます。しかし、以下の場合は速やかに獣医師を受診してください。

- 水を全く飲まない
- 嘔吐・下痢が続いている
- ぐったりして動かない
- 高齢のペットで脱水症状が見られる

脱水は放置すると臓器に深刻なダメージを与える可能性があります。早めの対応が重要です。

## まとめ

犬と猫の水分補給は健康維持の基本です。脱水のサインを知り、水飲み場の工夫・ウェットフードの活用・飲み水のこまめな入れ替えで、十分な水分摂取をサポートしましょう。飲み水に栄養をプラスする方法も、効率的なケアとして注目されています。

[ココペリ](/checkout)は飲み水に数滴加えるだけで使える、水溶性ケイ素の動物用栄養補助食品です。毎日の水分補給と一緒に、手軽に栄養ケアを始められます。
    `,
