シリカ水・ミネラルウォーター・水道水いずれも、開封後・給水後はミネラル分があるため**雑菌増殖の格好の培地**です。

未開封の保管環境と開封後のローテーション運用をルール化することで、ペットの消化器・尿路の健康を守ることができます。

